  // raw counts (rare events — no >>6 downscale). Zero while emission is
  // dormant; the ONLY reliable "gates fired" signal (realizedSkip and the
  // tier counters are mode-entangled).
  gateJumps: atomic<u32>,
  gateFails: atomic<u32>,
