  out.extras.height = geometry.w;
  out.extras.gradient = geometry.xy;
  out.extras.curvature = geometry.z;
  out.extras.geometryAngle = select(0.0, atan2(geometry.y, geometry.x), dot(geometry.xy, geometry.xy) > 1e-12);
