      frozenGeometryTex,
      frozenMetadataTex,
      frozenOrbitGradientTex,
      frozenTrapPayloadTex,
      frozenCoord,
      texSize,
      frozen_iter,
      frozen_zx,
      frozen_zy,
      frozenInterp,
      uv_screen,
      uv_neutral,
      zf,
      false
